pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    function testFuzz_property(address from, address caddress, address[] calldata tos, uint v, uint decimals) public {
        vm.assume(tos.length > 0);
        Reverter reverter = new Reverter();
        address[] memory failingTos = new address[](tos.length);
        for (uint i = 0; i < tos.length; i++) {
            failingTos[i] = address(reverter);
        }

        bool ret;
        bool ok;
        try c.transfer(from, caddress, failingTos, v, decimals) returns (bool r) {
            ret = r;
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || ret);
    }
}

contract Reverter { fallback() external payable { revert(); } }
